CREATE TABLE IF NOT EXISTS tabor_compute_fleet (node_id TEXT PRIMARY KEY, provider TEXT NOT NULL, kind TEXT NOT NULL, cpu_cores INTEGER, ram_gb REAL, storage_gb REAL, miner_type TEXT, endpoint_label TEXT, last_heartbeat TEXT, heartbeat_count INTEGER NOT NULL DEFAULT 0, verification_state TEXT NOT NULL DEFAULT 'unverified', created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS tabor_compute_heartbeats (id INTEGER PRIMARY KEY AUTOINCREMENT,node_id TEXT NOT NULL REFERENCES tabor_compute_fleet(node_id),reported_at TEXT NOT NULL,received_at TEXT DEFAULT CURRENT_TIMESTAMP,cpu_load REAL,ram_used_gb REAL,hashrate_ths REAL,bitcoin_height INTEGER,software_version TEXT,UNIQUE(node_id,reported_at));CREATE INDEX IF NOT EXISTS tabor_compute_heartbeats_node ON tabor_compute_heartbeats(node_id,id DESC);